/* @lc app=leetcode id=3478 lang=kotlin */ class Solution { fun findMaxSum(nums1: IntArray, nums2: IntArray, k: Int): LongArray = LongArray(nums1.size).also { res -> java.util.PriorityQueue<Int>().let { pq -> LongArray(1).let { sm -> nums1.indices.groupBy { nums1[it] }.toSortedMap().values.forEach { grp -> grp.forEach { res[it] = sm[0] }.let { grp.forEach { i -> pq.add(nums2[i]).also { sm[0] += nums2[i] }.also { if (pq.size > k) sm[0] -= pq.poll() } } } } } } } }